def head(title):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' · Ashley Heights</title><link rel="icon" href="data:,"><link rel="stylesheet" href="studio.css"><style>'+style+'</style></head><body>'+header
for stem,r in rooms.items():
 meta=json.loads((PUBLIC/'models'/('compact-'+stem+'.json')).read_text());config={'modelStem':stem,'fullHouseRoom':r['fullRoom'],'planAsset':stem+'-plan.svg','maxDistance':25,'noGarden':True,'views':meta['views'],'viewLabels':meta['configuration'].get('viewLabels',{}),'variants':r.get('variants',['compact','planning'])}
 shutil.copyfile(ROOT/'revisions/interiors-overnight-2026-09-27'/stem/r['plan'],PUBLIC/(stem+'-plan.svg'))
 design_options=''.join('<option value="'+v+'">'+('Proposed'if v=='compact'else'Proposed · planning application')+'</option>'for v in config['variants'])
 buttons=''.join(f'<button data-camera="{key}" aria-pressed="{str(key=="entrance").lower()}">{config.get('viewLabels',{}).get(key,labels.get(key,key.replace('-', ' ').title()))}</button>'for key in config['views'])
 nav='<nav class="room-nav" aria-label="Room studies">'+''.join(f'<a href="{s}.html" data-study="{s}.html"'+(' aria-current="page"'if s==stem else'')+'>'+rr['title']+'</a>'for s,rr in rooms.items())+'</nav>'
 copy=''.join('<h2>'+title+'</h2><p>'+body+'</p>'for title,body in r['copy'])
 html=head(r['title'])+'<main>'+nav+'<section class="intro"><div><p class="eyebrow">'+r['title'].upper()+' / ROOM DEVELOPMENT 01</p><h1>'+r['headline']+'</h1><p>'+r['intro']+'</p></div><label class="design-label">Viewing design<select id="model-design">'+design_options+'</select></label></section><nav class="model-tools" aria-label="Room views">'+buttons+'<button id="reset-model">Reset view</button></nav><div class="model-area"><canvas id="room-model" aria-label="Interactive 3D room. Drag to orbit, scroll to zoom, right-drag to pan."></canvas><div id="model-status" class="model-status" role="status">Loading your room…</div></div><p class="model-caption">Drag to look around · scroll to zoom · right-drag to pan. The ceiling is removed only in the cutaway.</p><div class="room-copy">'+copy+'</div><img id="layout-plan" class="plan" alt="Measured room arrangement and activity clearances"><p class="model-caption">Developed concept for review. Dimensions come from the model. Furniture access, viewing and simultaneous-use checks are recorded separately from construction feasibility.</p></main><footer>Ashley Heights · '+r['title']+' / 01</footer><script>window.INTERIOR_PREVIEW_CONFIG='+json.dumps(config)+';document.querySelectorAll("[data-study]").forEach(a=>a.href=a.dataset.study+"?design="+(new URLSearchParams(location.search).get("design")==="planning"?"planning":"compact"));</script><script type="module" src="room-model.js"></script></body></html>'
 (PUBLIC/(stem+'.html')).write_text(html)
cards=''.join('<a class="card" href="'+s+'.html"><h2>'+r['title']+'</h2><p>'+r['intro']+'</p><span>Explore the room →</span></a>'for s,r in rooms.items())
(PUBLIC/'index.html').write_text(head('Room studies')+'<main><section class="intro"><div><p class="eyebrow">ROOM DEVELOPMENT</p><h1>The next rooms, thoughtfully arranged.</h1><p>Warm oak, limestone and ivory carry through the house, with darker finishes around the cinema screen.</p></div></section><div class="cards">'+cards+'</div><p><a href="../principal/bedroom.html">Principal suite ↗</a> · <a href="../kitchen/model.html">Kitchen &amp; TV lounge ↗</a></p></main><footer>Ashley Heights · Interior design studio</footer></body></html>')
print('Built leisure room review pages')
